/* ─── Nav data ─── */
const navItems = [
  { text: "Parade Info",   link: "#parade-info" },
  { text: "Evening Event", link: "#evening-event" },
  { text: "Competition",   link: "#drill-team" },
  { text: "Gallery",       link: "#gallery" },
  { text: "About",         link: "#about" },
]

/* ─── Page ─── */
const IndexPage = () => {
  const [drawerOpen, setDrawerOpen] = useState(false)
  const [scrolled, setScrolled]     = useState(false)

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 60)
    window.addEventListener("scroll", onScroll, { passive: true })
    return () => window.removeEventListener("scroll", onScroll)
  }, [])

  const container = typeof window !== "undefined" ? () => window.document.body : undefined

  return (
    <React.Fragment>
      <GlobalStyles />

      {/* ── Navbar ── */}
      <StyledAppBar position="fixed" scrolled={scrolled ? 1 : 0}>
        <Toolbar sx={{ minHeight: { xs: "64px", md: "72px" }, px: { xs: "16px", md: "40px" } }}>
          <LogoWrap>
            <a href="/"><NavLogo src="./619 Juneteenth in the Dotte Logo v1.svg" alt="Juneteenth in the Dotte" /></a>
          </LogoWrap>
          <DesktopNav>
            {navItems.map(i => <NavLink key={i.link} href={i.link}>{i.text}</NavLink>)}
            <NavCTA href="mailto:jnthedotte@gmail.com">Contact Us</NavCTA>
          </DesktopNav>
          <MobileBtn aria-label="Open navigation menu" onClick={() => setDrawerOpen(true)}>
            <HamIcon><span /><span /><span /></HamIcon>
          </MobileBtn>
        </Toolbar>
      </StyledAppBar>

      {/* ── Mobile Drawer ── */}
      <Drawer
        container={container}
        variant="temporary"
        anchor="right"
        open={drawerOpen}
        onClose={() => setDrawerOpen(false)}
        sx={{ "& .MuiDrawer-paper": { width: "100%", boxSizing: "border-box" } }}
      >
        <DrawerWrap>
          <DrawerHead>
            <DrawerLogo src="./619 Juneteenth in the Dotte Logo v1.svg" alt="Juneteenth in the Dotte" />
            <DrawerClose onClick={() => setDrawerOpen(false)} aria-label="Close menu">✕</DrawerClose>
          </DrawerHead>
          <DrawerLinks>
            {navItems.map(i => (
              <DrawerLink key={i.link} href={i.link} onClick={() => setDrawerOpen(false)}>
                {i.text}
              </DrawerLink>
            ))}
          </DrawerLinks>
          <DrawerCTA href="mailto:jnthedotte@gmail.com">Contact Us</DrawerCTA>
        </DrawerWrap>
      </Drawer>

      {/* ── Hero ── */}
      <HeroWrap>
        <HeroBg />
        <HeroPattern />
        <HeroOverlay />
        <HeroPanAfricanBar />
        <HeroContent>
          <HeroEyebrow>
            <HeroPill>Kansas City, KS · Est. Annual</HeroPill>
            <HeroAccent />
          </HeroEyebrow>
          <HeroTitle>Juneteenth<br />in the Dotte</HeroTitle>
          <HeroDate>Saturday, June 13, 2026</HeroDate>
          <HeroSubtitle>
            Join us for the Annual Juneteenth Parade — celebrating freedom,
            culture, and community in Wyandotte County.
          </HeroSubtitle>
          <HeroActions>
            <HeroBtnPrimary href="./2026Waiver.pdf" target="_blank" rel="noreferrer">
              Join the Parade
            </HeroBtnPrimary>
            <HeroBtnGhost href="#parade-info">Event Details</HeroBtnGhost>
          </HeroActions>
        </HeroContent>
        <ScrollHint onClick={() => document.getElementById("ann-strip")?.scrollIntoView({ behavior: "smooth" })}>
          <ScrollLine />
          <ScrollLabel>Scroll</ScrollLabel>
        </ScrollHint>
      </HeroWrap>

      {/* ── Announcement strip ── */}
      <AnnStrip id="ann-strip">
        🎉&nbsp;&nbsp;Registration is open — Entry Deadline May 31, 2026&nbsp;&nbsp;·&nbsp;&nbsp;
        <a href="./2026Waiver.pdf" target="_blank" rel="noreferrer"
           style={{ textDecoration: "underline", textUnderlineOffset: "3px", opacity: 0.85 }}>
          Download the 2026 Waiver
        </a>
        &nbsp;&nbsp;🎉
      </AnnStrip>

      {/* ── Countdown Timer ── */}
      <CountdownTimer />

      {/* ── Stats bar ── */}
      <StatsBar>
        <StatsInner>
          <StatItem>
            <StatNumber>2026</StatNumber>
            <StatLabel>Annual Celebration</StatLabel>
          </StatItem>
          <StatItem>
            <StatNumber>June 13</StatNumber>
            <StatLabel>Parade Date</StatLabel>
          </StatItem>
          <StatItem>
            <StatNumber>9 AM</StatNumber>
            <StatLabel>Parade Kickoff</StatLabel>
          </StatItem>
          <StatItem>
            <StatNumber>6–9:30p</StatNumber>
            <StatLabel>Evening at Kaw Point</StatLabel>
          </StatItem>
        </StatsInner>
      </StatsBar>

      {/* ── Parade Cards ── */}
      <ParadeCards />

      {/* ── Evening Event ── */}
      <EveningEvent />

      {/* ── Drill Team Callout ── */}
      <DrillTeamCallout />

      {/* ── Photo Grid Gallery ── */}
      <PhotoGrid />

      {/* ── About ── */}
      <GoldSection id="about">
        <GoldInner>
          <GoldEyebrow>— About Us</GoldEyebrow>
          <GoldTitle>Juneteenth in the Dotte</GoldTitle>
          <GoldBar />
          <GoldPullQuote>
            "The longest-running African-American holiday — America's Second Independence Day."
          </GoldPullQuote>
          <GoldBody>
            Juneteenth in the Dotte exists to promote Wyandotte County's Annual Juneteenth Parade.
            Our committee recognizes this holiday as a celebration of freedom, resilience, and
            community — honored every year on the third Saturday in June.
          </GoldBody>
          <CommitGrid>
            <CommitCard>
              <CommitTitle>Participation</CommitTitle>
              <CommitText>
                Providing opportunities for local organizations and individuals of all backgrounds
                to participate and compete in prize categories.
              </CommitText>
            </CommitCard>
            <CommitCard>
              <CommitTitle>Community</CommitTitle>
              <CommitText>
                Creating a greater sense of an empowered and educated community throughout
                the Wyandotte County area.
              </CommitText>
            </CommitCard>
            <CommitCard>
              <CommitTitle>Culture</CommitTitle>
              <CommitText>
                Uniquely contributing to the quality, vitality, and cultural richness
                of the Wyandotte County community.
              </CommitText>
            </CommitCard>
          </CommitGrid>
        </GoldInner>
      </GoldSection>

      {/* ── Sticky Mobile CTA ── */}
      <StickyBar />

      {/* ── Footer ── */}
      <Footer />
    </React.Fragment>
  )
}

export default IndexPage